<?php
defined('BASEPATH') or exit('No direct script access allowed');
class Pipeline_customers extends CI_Controller {
 public function __construct(){parent::__construct();is_login();$this->load->library('Pipeline_access');$this->pipeline_access->require_menu('customer_accounts');$this->load->model('Pipeline_user_model','users');if(!$this->session->userdata('pipeline_form_token'))$this->session->set_userdata('pipeline_form_token',bin2hex(random_bytes(24)));}
 public function index(){ $error='';if($this->input->method()==='post'){$token=$this->input->post('pipeline_token');if(!is_string($token)||!hash_equals($this->session->userdata('pipeline_form_token'),$token))show_error('Form kedaluwarsa.',403);try{$v=$this->input->post('AccessVersion');if(!is_string($v)||!ctype_digit($v))throw new RuntimeException('Versi tidak valid.');$this->users->bind_customer($this->input->post('UserID'),$this->input->post('NIB'),$this->input->post('CompanyName'),$this->session->userdata('MIS_LOGGED_ID'),(int)$v);$this->session->set_flashdata('Berhasil','Badan usaha Customer tersimpan. Customer perlu login kembali. Atur hak menu dan area melalui Access Management.');redirect('Pipeline_customers');return;}catch(Exception $e){$error=$e->getMessage();}}
  $customers=$this->db->select('L.UserID,L.UserName,L.Email,L.Active,L.BusinessEntityID,B.NIB,B.CompanyName,ISNULL(S.AccessVersion,1) AccessVersion',false)->from('Login L')->join('JbtBusinessEntity B','B.BusinessEntityID=L.BusinessEntityID','left')->join('PipelineUserSecurity S','S.UserID=L.UserID','left')->where('L.UserRole','CUSTOMER')->where('S.DeletedAt IS NULL',null,false)->order_by('L.UserName')->get()->result_array();$entities=$this->db->where('IsActive',1)->order_by('CompanyName')->get('JbtBusinessEntity')->result_array();$companyHistory=$this->db->query("SELECT R.RequestID,R.RequestNo,R.Status,JSON_VALUE(R.Letter,'$.CompanyName') SavedCompany,B.CompanyName CurrentCompany
FROM PipelineFlowRequest R JOIN JbtBusinessEntity B ON B.BusinessEntityID=R.BusinessEntityID
WHERE ISJSON(R.Letter)=1 AND JSON_VALUE(R.Letter,'$.CompanyName')<>B.CompanyName ORDER BY R.RequestID DESC")->result_array();$data=compact('customers','entities','error','companyHistory');$data['judul']='Admin Kapal / Customers';$data['pipeline_token']=$this->session->userdata('pipeline_form_token');$this->load->view('templates/header',$data);$this->load->view('templates/sidebar');$this->load->view('pipeline/customer_accounts',$data);$this->load->view('templates/footer');
 }
}
